```javascript
function moveCard(card, direction) {
    const columns = ['s9-todo', 's9-doing', 's9-done'];
    const currentColumn = card.parentElement.id;
    const currentIndex = columns.indexOf(currentColumn);

    if (direction === 'left' && currentIndex > 0) {
        // Move to previous column
        const targetColumn = document.getElementById(columns[currentIndex - 1]);
        targetColumn.querySelector('ul').appendChild(card);
    } else if (direction === 'right' && currentIndex < columns.length - 1) {
        // Move to next column
        const targetColumn = document.getElementById(columns[currentIndex + 1]);
        targetColumn.querySelector('ul').appendChild(card);
    }
}

// Add event listeners for card buttons
document.addEventListener('click', function(e) {
    if (e.target.classList.contains('s9-left')) {
        moveCard(e.target.closest('.s9-card'), 'left');
    } else if (e.target.classList.contains('s9-right')) {
        moveCard(e.target.closest('.s9-card'), 'right');
    }
});
```

